program.source:
SubProceso Intercambiar(a Como Entero, b Como Entero)
  Definir guardado Como Entero <- a;
  a <- b;
  b <- guardado;
FinSubProceso

Algoritmo Principal
  Definir primero, segundo Como Entero;
  Leer primero;
  Leer segundo;
  Intercambiar(primero, segundo);
  Escribir primero, " ", segundo;
FinAlgoritmo

